<?php include 'auth.php'; include 'conection.php'; $id=(int)($_GET['id']??0); if($id<1) die('ID siswa tidak valid.'); $q=$conn->prepare('SELECT * FROM siswa WHERE id_siswa=?'); $q->bind_param('i',$id); $q->execute(); $data=$q->get_result()->fetch_assoc(); if(!$data) die('Siswa tidak ditemukan.'); if($_SERVER['REQUEST_METHOD']==='POST'){ $nisn=trim($_POST['nisn']??''); $nama=trim($_POST['nama_siswa']??''); $kelas=trim($_POST['kelas']??''); $jurusan=trim($_POST['jurusan']??''); $alamat=trim($_POST['alamat']??''); $pw=$_POST['password']??''; if($pw!==''){ $hash=password_hash($pw,PASSWORD_DEFAULT); $u=$conn->prepare('UPDATE siswa SET nisn=?,nama_siswa=?,kelas=?,jurusan=?,alamat=?,password=? WHERE id_siswa=?'); $u->bind_param('ssssssi',$nisn,$nama,$kelas,$jurusan,$alamat,$hash,$id); } else { $u=$conn->prepare('UPDATE siswa SET nisn=?,nama_siswa=?,kelas=?,jurusan=?,alamat=? WHERE id_siswa=?'); $u->bind_param('sssssi',$nisn,$nama,$kelas,$jurusan,$alamat,$id); } if($u->execute()) header('Location: siswa.php'); else die('Gagal mengubah siswa: '.htmlspecialchars($u->error)); }
?><!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><title>Edit Siswa</title><link rel="stylesheet" href="./data.css?v=spiderman2026"></head><body><div class="container small"><div class="form-card"><p class="eyebrow">DATA SISWA</p><h1>Edit Siswa</h1><form method="post"><div class="form-group"><label>NISN</label><input type="text" name="nisn" value="<?=htmlspecialchars($data['nisn'])?>" required></div><div class="form-group"><label>Nama Siswa</label><input type="text" name="nama_siswa" value="<?=htmlspecialchars($data['nama_siswa'])?>" required></div><div class="form-group"><label>Kelas</label><input type="text" name="kelas" value="<?=htmlspecialchars($data['kelas'])?>" required></div><div class="form-group"><label>Jurusan</label><input type="text" name="jurusan" value="<?=htmlspecialchars($data['jurusan'])?>" required></div><div class="form-group"><label>Alamat</label><textarea name="alamat"><?=htmlspecialchars($data['alamat']??'')?></textarea></div><div class="form-group"><label>Password Login Baru <span style="color:#98a2b3">(kosongkan jika tidak diubah)</span></label><input type="password" name="password" autocomplete="new-password"></div><div class="actions"><a href="siswa.php" class="btn btn-secondary">Kembali</a><button class="btn btn-primary">Simpan Perubahan</button></div></form></div></div></body></html>
